-- Dungeon Journal: TBC raid quests and attunements.
-- Source: "TBC Raid Quests and Complete Attunements" v2 (22 Oct 2026, quest + reward item IDs),
-- supplied by the author. Final reward quest is the entry; every earlier step is
-- in its chain. Missing ring-step IDs (Down the Violet Path / Distinguished
-- Service) checked on Wowhead (10729 -> 10733 -> 10738 -> 10725). No dailies.
local _, FDJ = ...
FDJ = FDJ or _G.ForeverDungeonJournal_NS
if not FDJ or not FDJ.IS_TBC_ANNIVERSARY or not FDJ.DB then return end
FDJ.QUEST_PREREQ_CHAINS = FDJ.QUEST_PREREQ_CHAINS or {}
FDJ.QUEST_PREREQ_DETAILS = FDJ.QUEST_PREREQ_DETAILS or {}

local function Add(raid, q)
    local d = FDJ.DB[raid]
    if not d then return end
    d.quests = d.quests or {}
    for _, existing in ipairs(d.quests) do
        if existing.id == q.id and (existing.faction or "Both") == (q.faction or "Both") then return end
    end
    local copy = {}
    for k, v in pairs(q) do copy[k] = v end
    copy.tbcRaidQuest = true
    table.insert(d.quests, copy)
end

